query:
SELECT DISTINCT ?class ?item ?itemLabel ?coord ?country ?countryLabel ?countryCode ?statusLabel ?inception ?dissolved WHERE {
      VALUES ?class { wd:Q134447 wd:Q1438105 wd:Q188589 wd:Q1360597 wd:Q11536219 wd:Q5446866 wd:Q3966636 }
      ?item wdt:P31 ?class; wdt:P625 ?coord.
      OPTIONAL { ?item wdt:P17 ?country. OPTIONAL { ?country wdt:P297 ?countryCode. } }
      OPTIONAL { ?item wdt:P5817 ?status. } OPTIONAL { ?item wdt:P571 ?inception. } OPTIONAL { ?item wdt:P576 ?dissolved. }
      SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
    }
